'use strict';
class WorldConnection {
  socket=null;character=null;generation=0;retry=0;moveTime=0;stopped=false;
  async api(path,data){const response=await fetch('/api/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const type=response.headers.get('Content-Type')||'';if(!type.includes('application/json'))throw Error('Backend online indisponível neste endereço. A prévia solo continua disponível.');const value=await response.json();if(!response.ok)throw Error(({slot_limit:'Todos os dez slots estão ocupados.',unauthorized:'Entre novamente na sua conta.',rate_limited:'Muitas tentativas. Aguarde um minuto.',invalid_credentials:'Confira e-mail e senha (mínimo 12 caracteres).',conflict:'Já existe uma conta com este e-mail.'})[value.error]||'Ação não aceita pelo servidor.');return value;}
  async chooseCharacter(){try{const data=await this.api('characters');$('#creator').close();const r=$('#roster');r.replaceChildren(...data.characters.map(c=>{const n=document.createElement('button');n.type='button';n.textContent=c.name+' · '+c.animal+' · '+c.continent;n.onclick=()=>this.join(c).catch(e=>notice(e.message));return n;}));$('#creator').showModal();$('#closeCreator').hidden=false;$('#form .primary').disabled=data.characters.length>=10;}catch(e){notice(e.message);}}
  async createCharacter(data){try{await this.api('characters',{name:String(data.get('name')),continent:String(data.get('origin')),animal:String(data.get('animal'))});await this.chooseCharacter();notice('Personagem criado no servidor. Selecione-o abaixo para jogar.');}catch(e){notice(e.message);}}
  async join(c){this.character=c;this.stopped=false;fetch('/godot/index.html',{method:'HEAD'}).then(r=>{const b=document.querySelector('#godotClient');b.hidden=!r.ok;b.onclick=()=>location.assign('/godot/index.html?character='+encodeURIComponent(c.id));}).catch(()=>{});const generation=++this.generation;if(this.socket){this.socket.onclose=null;this.socket.close();}const result=await this.api('ticket',{character_id:c.id});if(generation!==this.generation)return;const url=new URL('/api/ws',location.href);url.protocol=location.protocol==='https:'?'wss:':'ws:';url.searchParams.set('ticket',result.ticket);const socket=new WebSocket(url);this.socket=socket;socket.onopen=()=>{this.retry=0;$('#creator').close();notice('Conectado ao continente. O servidor controla seu progresso.');};socket.onmessage=e=>{try{this.snapshot(JSON.parse(e.data));}catch{notice('Resposta inválida do servidor.');}};socket.onclose=e=>{if(generation!==this.generation||this.stopped)return;if(e.code===1000&&e.reason==='replaced'){this.stopped=true;notice('Este personagem foi conectado em outra sessão.');return;}const delay=Math.min(30000,1000*2**this.retry++)+Math.random()*500;notice('Conexão perdida. Reconectando…');setTimeout(()=>{if(generation===this.generation&&!this.stopped)this.join(c).catch(err=>notice(err.message));},delay);};socket.onerror=()=>socket.close();}
  snapshot(data){if(data.type==='error'){notice('O servidor rejeitou essa ação.');return;}if(data.type!=='snapshot'||!Array.isArray(data.players))return;const c=data.players.find(p=>p.id===data.self);if(!c)return;const inventory=data.inventory;player={...(player||{}),...c,origin:c.continent,bag:{fruit:inventory.fruit,plant:inventory.plant,liquid:inventory.liquid,coin:inventory.coin,potion:inventory.potion,cloth:inventory.cloth},cards:inventory.cards,hp:inventory.hp,nation:0,customNation:c.nation_id,collected:0,crafted:0};clock=data.server_time/1000;morphUntil=c.morph_until/1000;remotePlayers=data.players.filter(p=>p.id!==data.self);resources.length=0;for(const n of data.nodes||[])resources.push({...n,type:n.kind,ready:0});raid=data.raid?{...data.raid,x:0,z:7,ends:data.raid.ends/1000}:null;weatherIndex=Math.floor(data.server_time/40000)%3;ui();$('#slots').textContent='ONLINE';$('#nationText').textContent='Estado sincronizado com o servidor.';}
  intent(value){if(this.socket?.readyState===WebSocket.OPEN)this.socket.send(JSON.stringify(value));else notice('Aguarde a conexão com o servidor.');}
  move(dx,dz){if(performance.now()-this.moveTime<65||(!dx&&!dz))return;this.moveTime=performance.now();this.intent({type:'move',dx,dz});}
  collect(){const node=resources.filter(n=>distance(player,n)<2.5).sort((a,b)=>distance(player,a)-distance(player,b))[0];if(!node){notice('Aproxime-se de um recurso.');return;}this.intent({type:'collect',target:node.id});}
  attack(){if(raid&&distance(player,{x:0,z:7})<3){this.intent({type:'attack',target:'boss'});return;}const enemy=remotePlayers.find(p=>p.z>4&&player.z>4&&p.nation_id!==player.customNation&&distance(player,p)<2.5);if(!enemy){notice('Nenhum adversário ao alcance na fronteira.');return;}this.intent({type:'attack',target:enemy.id});}
}
net=new WorldConnection();
$('#connect').onclick=()=>$('#login').showModal();
$('#loginForm').onsubmit=async e=>{e.preventDefault();const form=e.target,button=e.submitter;button.disabled=true;$('#loginStatus').textContent='Conectando…';try{const data=new FormData(form);await net.api(button.value,{email:String(data.get('email')),password:String(data.get('password'))});online=true;target=null;keys.clear();player=null;$('#login').close();$('#creator').close();document.querySelector('.badge').textContent='ONLINE · SERVIDOR AUTORITATIVO';$('#connect').textContent='Conta conectada';await net.chooseCharacter();}catch(error){$('#loginStatus').textContent=error.message;}finally{button.disabled=false;}};
